Use a value stack, popping the right operand before the left. Division uses Math.trunc to truncate toward zero. Time: O(n); space: O(n).

```javascript
function solve(tokens) {
  const stack = [];

  for (const token of tokens) {
    if (
      token === '+' || token === '-' ||
      token === '*' || token === '/'
    ) {
      const right = stack.pop();
      const left = stack.pop();

      switch (token) {
        case '+':
          stack.push(left + right);
          break;
        case '-':
          stack.push(left - right);
          break;
        case '*':
          stack.push(left * right);
          break;
        case '/':
          stack.push(Math.trunc(left / right));
          break;
      }
    } else {
      stack.push(Number(token));
    }
  }

  return stack.pop();
}
```

