Use a stack to save each enclosing text and repetition count, then expand the inner text when its closing bracket arrives.

```javascript
function solve(s) {
  const stack = [];
  let parts = [];
  let count = 0;

  for (const char of s) {
    if (char >= '0' && char <= '9') {
      count = count * 10 + Number(char);
    } else if (char === '[') {
      stack.push({ parts, count });
      parts = [];
      count = 0;
    } else if (char === ']') {
      const inner = parts.join('');
      const frame = stack.pop();
      parts = frame.parts;
      parts.push(inner.repeat(frame.count));
    } else {
      parts.push(char);
    }
  }

  return parts.join('');
}
```

